_out_meta_skip = {'__type'}

def _clean_out_meta(o):
    "A copy of output `o` without transient metadata; never mutates the live output"
    o = dict(o)
    if m := o.get('metadata'): o['metadata'] = {k:v for k,v in m.items() if k not in _out_meta_skip}
    return o

