CUR_VER = 3

def nb_ver(nb):
    "Stored notebook version; unversioned files start at v1"
    meta = nb.get('metadata', {})
    return meta.get('solveit', {}).get('ver', meta.get('solveit_ver', 1))

# %% ../nbs/02_ipynb.ipynb #migratev1
def _v1_to_v2(nb):
    meta = nb.setdefault('metadata', {})
    sv = meta.get('solveit', {})
    modes = {1:'standard', 2:'learning', 3:'concise'}
    if isinstance(sv.get('mode'), int): sv['mode'] = modes[sv['mode']]
    if isinstance(meta.get('solveit_dialog_mode'), int): meta['solveit_dialog_mode'] = modes[meta['solveit_dialog_mode']]

# %% ../nbs/02_ipynb.ipynb #migratev2
def _v2_to_v3(nb):
    meta = nb.setdefault('metadata', {})
    sv = meta.setdefault('solveit', {})
    if 'solveit_dialog_mode' in meta: sv.setdefault('mode', meta.pop('solveit_dialog_mode'))
    meta.pop('solveit_ver', None)
    conv_old_prompts(nb)
    for c in nb['cells']:
        if not c['metadata'].get('solveit_ai'): continue
        for o in c.get('outputs', []):
            md = nested_idx(o, 'metadata', 'is_ai_res') and nested_idx(o, 'data', 'text/markdown')
            if not md: continue
            if '-usage-details' in md: o['data']['text/markdown'] = conv_tools(md)

# %% ../nbs/02_ipynb.ipynb #migratenb
_migrations = {1:_v1_to_v2, 2:_v2_to_v3}

def migrate_nb(nb):
    "Upgrade a normalized notebook in place. Return whether its version changed"
    ver = nb_ver(nb)
    if not 1 <= ver <= CUR_VER: raise ValueError(f'Unsupported notebook version: {ver}')
    for v in range(ver, CUR_VER):
        _migrations[v](nb)
        nb.setdefault('metadata', {}).setdefault('solveit', {})['ver'] = v+1
    return ver < CUR_VER

# %% ../nbs/02_ipynb.ipynb #10a73cfc
def get_ipynb(dlg:Dialog, msgs=None):
    "Notebook object for `dlg`; `msgs` defaults to all its messages"
    cells = [m.to_cell() for m in (dlg.messages if msgs is None else msgs)]
    meta = dict(dlg.meta)
    meta['solveit'] = dict(meta.get('solveit', {}), ver=CUR_VER)
    nb = new_nb(cells=cells, meta=meta)
    home_atts(nb)
    if repairs := repair_nb(nb): print('NB repair:', '; '.join(repairs))
    return nb


# %% ../nbs/02_ipynb.ipynb #8fa39210
def safe_mtime(p):
    "mtime of `p`, its symlink if the target is missing, or None if `p` vanished (e.g. an atomic-save temp file)"
    with suppress(FileNotFoundError): return p.stat().st_mtime
    with suppress(FileNotFoundError): return p.stat(follow_symlinks=False).st_mtime

# %% ../nbs/02_ipynb.ipynb #ea5fa1dd
def write_ipynb(dlg:Dialog, fname=None, msgs=None, **kwargs):
    "Write `dlg` as a notebook, or return the JSON string if `fname` is None; `kwargs` (e.g. `uid`/`gid`) pass to `atomic_save`"
    res = nb2str(get_ipynb(dlg, msgs=msgs))
    if not fname: return res
    fname = Path(fname).expanduser()
    with atomic_save(fname, mode='w', encoding='utf-8', **kwargs) as f: f.write(res)
    dlg.mtime_ = safe_mtime(fname)
    dlg.migrated_ = False

# %% ../nbs/02_ipynb.ipynb #5527e596
@patch
def write(self:Dialog, base_path, msgs=None, **kwargs):
    write_ipynb(self, Path(base_path).expanduser()/f'{self.name}.ipynb', msgs=msgs, **kwargs)

# %% ../nbs/02_ipynb.ipynb #0e16e93a
def ipynb_cells(path, nm, prefix=None, suffix=None):
    tmpl = Path(path).expanduser()/f'{nm}.ipynb'
    if not tmpl.exists(): return []
    try: nb = read_nb(tmpl)
    except json.JSONDecodeError: return []
    if repairs := repair_nb(nb): print('NB repair:', '; '.join(repairs))
    migrate_nb(nb)
    unhome_atts(nb)
    return listify(prefix) + nb.cells + listify(suffix)

